(()=>{const s=document.createElement('style');s.id='companion-v120-style';s.textContent=".companion120Root{\n  position:fixed;\n  inset:0;\n  z-index:12000;\n  display:none;\n  place-items:center;\n  overflow:hidden;\n  background:#f8edf2;\n  overscroll-behavior:none;\n  touch-action:manipulation;\n}\n.companion120Root.is-active{display:grid}\n.companion120Frame{\n  position:relative;\n  width:min(100vw,66.6667dvh);\n  height:min(100dvh,150vw);\n  max-width:100vw;\n  max-height:100dvh;\n  overflow:hidden;\n  background:#f8edf2;\n  box-shadow:0 0 34px rgba(94,47,66,.18);\n}\n.companion120Art{display:block;width:100%;height:100%;object-fit:fill;user-select:none;-webkit-user-drag:none}\n.companion120Tap{\n  position:absolute;\n  display:block;\n  padding:0;\n  border:0;\n  border-radius:18px;\n  background:transparent;\n  color:transparent;\n  cursor:pointer;\n  -webkit-tap-highlight-color:transparent;\n}\n.companion120Tap:focus-visible{outline:4px solid #ff4e9b;outline-offset:2px;background:rgba(255,255,255,.16)}\n.companion120Toast{\n  position:absolute;\n  z-index:3;\n  left:50%;\n  bottom:9.2%;\n  translate:-50% 0;\n  width:max-content;\n  max-width:84%;\n  padding:.65rem 1rem;\n  border:3px solid #f29abb;\n  border-radius:999px;\n  background:rgba(255,255,255,.96);\n  color:#67304a;\n  font:800 clamp(13px,3.5vw,18px)/1.25 system-ui,sans-serif;\n  text-align:center;\n  box-shadow:0 6px 20px rgba(94,47,66,.2);\n  opacity:0;\n  transform:translateY(8px);\n  transition:.18s ease;\n  pointer-events:none;\n}\n.companion120Toast.is-on{opacity:1;transform:translateY(0)}\nbody.companion120Locked{overflow:hidden!important;height:100dvh!important}\n@media (min-aspect-ratio:2/3){.companion120Frame{box-shadow:0 0 50px rgba(94,47,66,.22)}}\n@media (prefers-reduced-motion:reduce){.companion120Toast{transition:none}}\n";document.head.appendChild(s)})();
(()=>{
'use strict';
const base='';
const screens={
  home:{image:'data:image/jpeg;base64,',alt:'English Quest 首頁'},
  profile:{image:'data:image/jpeg;base64,',alt:'我的學習雷達圖'},
  pet:{image:'data:image/jpeg;base64,',alt:'熊妹的小屋'},
  play:{image:'data:image/jpeg;base64,',alt:'和熊妹一起玩'},
  rps:{image:'data:image/jpeg;base64,',alt:'猜拳小挑戰'},
  leftRight:{image:'data:image/jpeg;base64,',alt:'左右猜猜樂'}
};
const hotspots={
  home:[
    ['profile',3,1,29,9,'前往我的'],
    ['map',5,70,43,18,'前往闖關'],
    ['games',52,70,43,18,'前往遊戲'],
    ['wardrobe',5,88,43,11,'前往衣櫥'],
    ['shop',52,88,43,11,'前往商店']
  ],
  profile:[
    ['back',3,2,12,8,'返回'],
    ['home',2,91,17,8,'首頁'],['map',21,91,17,8,'地圖'],
    ['wardrobe',41,91,17,8,'衣櫥'],['pet',61,91,17,8,'寵物'],['profile',81,91,17,8,'我的']
  ],
  pet:[
    ['back',3,2,12,8,'返回'],
    ['feed',8,64,25,10,'餵食'],['play',37,64,25,10,'玩耍'],['work',66,64,27,10,'工作二十分鐘'],
    ['home',2,91,17,8,'首頁'],['map',21,91,17,8,'地圖'],
    ['wardrobe',41,91,17,8,'衣櫥'],['pet',61,91,17,8,'寵物'],['profile',81,91,17,8,'我的']
  ],
  play:[
    ['back',3,2,12,8,'返回'],
    ['leftRight',6,35,42,25,'左右猜猜'],['rps',52,35,42,25,'猜拳挑戰'],
    ['home',2,91,17,8,'首頁'],['map',21,91,17,8,'地圖'],
    ['wardrobe',41,91,17,8,'衣櫥'],['pet',61,91,17,8,'寵物'],['profile',81,91,17,8,'我的']
  ],
  rps:[
    ['back',3,2,12,8,'返回'],
    ['rock',13,67,22,11,'出石頭'],['scissors',39,67,22,11,'出剪刀'],['paper',65,67,22,11,'出布'],
    ['home',2,91,17,8,'首頁'],['map',21,91,17,8,'地圖'],
    ['wardrobe',41,91,17,8,'衣櫥'],['pet',61,91,17,8,'寵物'],['profile',81,91,17,8,'我的']
  ],
  leftRight:[
    ['back',3,2,12,8,'返回'],
    ['left',11,67,23,11,'猜左邊'],['middle',38,67,24,11,'猜中間'],['right',66,67,23,11,'猜右邊'],
    ['home',2,91,17,8,'首頁'],['map',21,91,17,8,'地圖'],
    ['wardrobe',41,91,17,8,'衣櫥'],['pet',61,91,17,8,'寵物'],['profile',81,91,17,8,'我的']
  ]
};
let current='home',previous='home',toastTimer=0,legacyGo=null;
const roots={};
function makeScreen(name){
  const info=screens[name],root=document.createElement('section');
  root.className='companion120Root';root.dataset.companion120=name;root.hidden=true;
  root.innerHTML=`<div class="companion120Frame"><img class="companion120Art" src="${base+info.image}" alt="${info.alt}"><div class="companion120Toast" role="status" aria-live="polite"></div></div>`;
  const frame=root.firstElementChild;
  (hotspots[name]||[]).forEach(([action,x,y,w,h,label])=>{
    const button=document.createElement('button');
    button.type='button';button.className='companion120Tap';button.dataset.c120=action;button.setAttribute('aria-label',label);
    Object.assign(button.style,{left:x+'%',top:y+'%',width:w+'%',height:h+'%'});frame.appendChild(button);
  });
  document.body.appendChild(root);roots[name]=root;
}
function hide(){Object.values(roots).forEach(r=>{r.classList.remove('is-active');r.hidden=true});document.body.classList.remove('companion120Locked')}
function show(name,remember=true){
  if(!roots[name])return;
  if(remember&&current!==name)previous=current;
  current=name;document.querySelectorAll('.page').forEach(p=>p.classList.remove('on'));hide();
  const root=roots[name];root.hidden=false;root.classList.add('is-active');document.body.classList.add('companion120Locked');window.scrollTo(0,0);
}
function route(id){
  if(['home','profile','pet','play','rps','leftRight'].includes(id)){show(id);return}
  hide();if(typeof legacyGo==='function')legacyGo(id);
}
function notify(message){
  const el=roots[current]?.querySelector('.companion120Toast');if(!el)return;
  clearTimeout(toastTimer);el.textContent=message;el.classList.add('is-on');toastTimer=setTimeout(()=>el.classList.remove('is-on'),2300);
}
function ensurePet(){
  if(typeof S==='undefined')return null;
  S.pet=S.pet||{};
  if(!Number.isFinite(S.pet.mood))S.pet.mood=90;
  if(!Number.isFinite(S.pet.intimacy))S.pet.intimacy=65;
  return S.pet;
}
function rewardPlay(){const pet=ensurePet();if(!pet)return;pet.mood=Math.min(100,pet.mood+5);pet.intimacy=Math.min(100,pet.intimacy+3);if(typeof save==='function')save()}
function playRps(action){
  const picks=['rock','scissors','paper'],labels=['石頭','剪刀','布'],mine=picks.indexOf(action),pet=Math.floor(Math.random()*3);
  const result=mine===pet?'平手！':(mine-pet+3)%3===2?'你贏了！':'熊妹贏了！';rewardPlay();
  notify(`你出${labels[mine]}，熊妹出${labels[pet]}：${result}　心情＋5・親密度＋3`);
}
function playLeftRight(action){
  const picks=['left','middle','right'],labels=['左邊','中間','右邊'],mine=picks.indexOf(action),pet=Math.floor(Math.random()*3);
  rewardPlay();notify(`${mine===pet?'猜對了！':'差一點！熊妹在'+labels[pet]}　心情＋5・親密度＋3`);
}
function shop(){hide();if(typeof legacyGo==='function')legacyGo('games');if(typeof game==='function')game('shop')}
function act(action){
  if(action==='back'){route(current==='profile'?'home':current==='pet'?'home':current==='play'?'pet':current==='rps'||current==='leftRight'?'play':previous);return}
  if(action==='shop'){shop();return}
  if(action==='games'){route('games');return}
  if(action==='feed'){
    const before=typeof S!=='undefined'?S.coins:0;if(typeof petAct==='function')petAct('feed');
    notify(typeof S!=='undefined'&&S.coins<before?'熊妹吃飽了！':'需要 10 枚金幣才能餵食');return;
  }
  if(action==='work'){if(typeof petAct==='function')petAct('work');notify('熊妹開始工作，20 分鐘後獲得 20 金幣');return}
  if(['rock','scissors','paper'].includes(action)){playRps(action);return}
  if(['left','middle','right'].includes(action)){playLeftRight(action);return}
  route(action);
}
function init(){
  Object.keys(screens).forEach(makeScreen);legacyGo=window.go;
  window.go=function(id){if(id==='home'||id==='pet'){route(id);return}hide();return typeof legacyGo==='function'?legacyGo(id):undefined};
  document.addEventListener('click',e=>{const b=e.target.closest('[data-c120]');if(!b)return;e.preventDefault();e.stopImmediatePropagation();act(b.dataset.c120)},true);
  if(document.getElementById('home')?.classList.contains('on'))show('home',false);
}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init);else init();
})();
